<?php
require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/csrf.php';$admin=require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['user_id']??0);if($id!== (int)$admin['id']){$pdo->prepare('UPDATE users SET is_active=1-is_active WHERE id=?')->execute([$id]);flash('success','User status updated. Disabled sellers are automatically hidden from public marketplace queries.');redirect('/admin/users.php');}}$items=$pdo->query("SELECT u.*,(SELECT COUNT(*) FROM listings WHERE user_id=u.id) listing_count,(SELECT COALESCE(AVG(rating),0) FROM reviews WHERE reviewed_user_id=u.id) rating FROM users u ORDER BY created_at DESC")->fetchAll();$pageTitle='Users';include dirname(__DIR__).'/includes/header.php';?>
<div class="section-head"><div><h2>Manage users</h2><p>Disabled accounts cannot sign in and their listings are hidden from public browsing without destroying marketplace history.</p></div></div><div class="table-wrap"><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Listings</th><th>Rating</th><th>Status</th><th>Action</th></tr><?php foreach($items as $x):?><tr><td><a href="/profile.php?id=<?=$x['id']?>"><?=e($x['name'])?></a></td><td><?=e($x['email'])?></td><td><?=e($x['role'])?></td><td><?=$x['listing_count']?></td><td><?=number_format((float)$x['rating'],1)?></td><td><?=$x['is_active']?'Active':'Disabled'?></td><td><?php if((int)$x['id']!==(int)$admin['id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=$x['id']?>"><button class="btn btn-sm <?=$x['is_active']?'btn-danger':'btn-light'?>"><?=$x['is_active']?'Disable':'Enable'?></button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__).'/includes/footer.php';?>
